23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	};
34	
35	const COMPONENT_BLOCK_SIZE = 3;
36	const COMPONENT_BLOCK_PREMIUM = 60;
37	
38	const sumBasePremiums = (items: Item[]): number => {
39	  if (items.length === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;
40	  return items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
41	};
42	
43	const quotePremium = (items: Item[]): number => {
44	  const base = sumBasePremiums(items);
45	  // Keep the surcharge additive (base + base * rate). The algebraically
46	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
47	  // which Math.ceil turns into a premium that is 1 G too high.
48	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
49	  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
50	};
51	
52	export const runScenario = (scenario: Scenario): Result[] =>
53	  scenario.steps.map((step) => {
54	    if (step.op === "quote") return { premium: quotePremium(step.items) };
55	    throw new Error(`Unsupported step: ${step.op}`);
56	  });
